<template>
<div class="dataset-detail" ref="scrollContainer">
    <!-- 1. 数据集选择区 -->
    <section class="dataset-selector card">
        <div class="selector-row">
            <h3 class="section-title">任务类型</h3>
            <div class="datasets-list">
                <span 
                    v-for="type in taskType?.[group?.task_type] || []" 
                    :key="type.name" 
                    class="dataset-badge"
                    :class="{ 'active': task_type_selected?.name === type.name }"
                    @click="toggleTaskType(type)"
                    tabindex="0"
                >
                    {{ type.alias }}
                </span>
            </div>
        </div>
        <div class="selector-row" v-if="task_type_selected?.subTasks">
            <h3 class="section-title">子任务类型</h3>
            <div class="datasets-list">
                <span 
                    v-for="type in task_type_selected?.subTasks || []" 
                    :key="type.name" 
                    class="dataset-badge"
                    :class="{ 'active': sub_task_type_selected?.name === type.name }"
                    @click="toggleSubTaskType(type)"
                    tabindex="0"
                >
                    {{ type.alias }}
                </span>
            </div>
        </div>
        <div class="selector-row">
            <h3 class="section-title">数据集类型</h3>
            <div class="datasets-list">
                <span 
                    v-for="type in datasetType || []" 
                    :key="type.name" 
                    class="dataset-badge"
                    :class="{ 'active': dataset_type_selected?.name === type.name }"
                    @click="toggleDatasetType(type)"
                    tabindex="0"
                >
                    {{ type.alias }}
                </span>
            </div>
        </div>
        <div class="selector-row">
            <h3 class="section-title">选择数据集</h3>
            <div class="datasets-list">
                <span 
                    v-for="dataset in datasetVisible || []" 
                    :key="dataset.value" 
                    class="dataset-badge"
                    :class="{ 'active': datasetSelected?.includes(dataset.value) }"
                    @click="selectDataset(dataset.value)"
                >
                    {{ dataset.label }}
                </span>
            </div>
            <el-button
                v-if="!group?.default || store.state.user_perms === 'administrator'"
                type="primary"
                @click="importDataset"
            >导入数据集
            </el-button>
        </div>
    </section>

    <!-- 2. 数据条目列表 -->
    <dataListImage
        :data_list = "data_list"
        :group_id = "group.id"
        :task_type= "sub_task_type_selected?.name"
        v-if="dataset_type_selected?.name == 'IMAGE'"
    >
    </dataListImage>
    <section class="data-list" v-else-if="dataset_type_selected?.name == 'INTERACTIVE_DIALOGUE'">     
        <el-card
            v-for="session in data_list"
            :key="session.session_code"
            class="session-item card"
            shadow="hover"
            @click="select_data(session.dataset_id, session.id)"
            >
            <!-- 卡片头部：展示 session_code 和 split -->
            <template #header>
