    <section class="data-list" v-else-if="dataset_type_selected?.name == 'ACCOUNT_ROLE_RECOGNITION'">
    <div
        v-for="(item, idx) in data_list"
        :key="idx"
        class="data-item card"
        @click="select_data(item.dataset_id, item.id)"
        >
